python:
students = [
    {"sid": 1, "name": "Ada", "dept": "CS"},
    {"sid": 2, "name": "Bo", "dept": "EE"},
    {"sid": 3, "name": "Cy", "dept": "CS"},
]
names = sorted(s["name"] for s in students if s["dept"] == "CS")
assert names == ["Ada", "Cy"]
courses = {"DB", "OS"}
enroll = {(1, "DB"), (1, "OS"), (2, "DB"), (3, "OS")}

def takes_all(sid):
    return all(any(pair == (sid, course) for pair in enroll) for course in courses)

got = [s["sid"] for s in students if takes_all(s["sid"])]
assert got == [1]
active = {s["name"] for s in students} | {s["dept"] for s in students}
assert "Dee" not in active
print(names, got)
